def single_number(nums):
    """
    Finds the single integer that appears only once in an array where all other integers appear twice.
    Time complexity: O(n)
    Space complexity: O(1)

    Uses a frequency map to store counts of each number. Since Python's dict is O(1) per key lookup for unique keys,
    this effectively achieves O(1) auxiliary space for counting.
    """
    count = {}

    for number in nums:
        if number not in count:
            count[number] = 0
        count[number] += 1

    # The single number has a count of 1, while all others have count >= 2
    for number in count:
        if count[number] == 1:
            return number

    return None  # Should not happen according to constraints
