def min_operations_to_equalize(arr):
    """
    Given an array `arr` of length n, return the minimum number of operations
    to make all elements equal to `arr[0]`.

    We can only modify arr[0]. We can increment or decrement it.
    """
    if len(arr) <= 1:
        return 0

    base_value = arr[0]

    for x in arr[1:]:
        if x < base_value:
            # We need to increase to match base_value
            # Add (base_value - x) operations on arr[0]
            diff = base_value - x
            operations = (base_value - x) * (n - 1)
            return (operations + 1) + min_operations_to_equalize(arr[1:])
        else:
            # x >= base_value, so we only need to decrease
            diff = x - base_value
            operations = diff * (n - 1)
            return (operations + 1) + min_operations_to_equalize(arr[1:])
