def remove_duplicates(s: str) -> str:
    """
    Return a new string t such that:
      - Each character from s appears in t exactly once.
      - If a character appears multiple times in s, only the first one is used.
    Return "" for an empty string.
    """
    if not s:
        return ""

    # Counter for first occurrence indices
    first_occurrence = {}

    for i, char in enumerate(s):
        if char in first_occurrence:
            first_occurrence[char] = i  # Keep first occurrence's index
        else:
            first_occurrence[char] = i

    # Create result string using only the first occurrence of each char
    result_chars = [char for char, _ in first_occurrence.values()]

    return "".join(result_chars)
