def remove_duplicates(s):
    """
    Return a new string `t` containing each character of `s` exactly once in the same order.
    Only the first appearance of each character is kept; later occurrences are ignored.

    For an empty string, return an empty string.

    Parameters:
        s (str): A string containing lowercase English letters.

    Returns:
        str: The new string after removing duplicates.
    """
    if not s:
        return ""

    # Counter to store the first appearance of each character
    first_seen = {}

    # First pass: count occurrences, mark first occurrence
    for char in s:
        if char in first_seen:
            first_seen[char] += 1
        else:
            first_seen[char] = 1

    # Second pass: collect only the first occurrence of each character
    result = []
    for char in s:
        if char in first_seen and first_seen[char] == 1:
            result.append(char)

    return "".join(result)
