def can_travel(routes, startCity, destinationCity):
    """
    Determines if it's possible to travel from startCity to destinationCity
    given a list of flights [cityA, cityB].

    Edge cases:
    - startCity == destinationCity: returns True
    - There are no routes: returns False
    - Graph may be disconnected or have cycles; uses Union-Find to detect reachability.
    """
    n = len(routes)

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]  # 1-indexed cities

    for i in range(n):
        route = routes[i]
        if len(route) != 2:
            return False  # Invalid route format
        u, v = route
        adj[u].append(v)
        adj[v].append(u)  # Flight bidirectional

    visited = [False] * (n + 1)
    parent = [-1] * (n + 1)  # Union-Find parent

    def find(x):
        if visited[x]:
            return x
        root = parent[x]
        if parent[root] == -1:
            return x
        return parent[x] = find(parent[x])

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False  # Already in same connected component
        parent[ry] = rx
        return True

    def connected(start, end):
        start_node = start
        end_node = end

        if start_node == end_node:
            return True

        stack = [(start_node, [end_node])]
        while stack:
            current, path = stack.pop()
            if current not in visited:
                visited[current] = True
                for neighbor in adj[current]:
                    if neighbor not in visited and neighbor != end_node:
                        stack.append((neighbor, path + [current]))
        return len(path) == 1  # Only direct path from start to end

    # Start and end are given as integers (1 to n)
    return connected(int(startCity), int(destinationCity))
