def can_travel(routes, startCity, destinationCity):
    """
    Determine if it is possible to travel from a starting city to a destination 
    using the given set of flights, treating flights as directed edges.

    Parameters:
        routes (list of list of str): List of bidirectional flights between cities.
        startCity (str): Start city.
        destinationCity (str): Destination city.

    Returns:
        bool: True if it is possible, False otherwise.
    """

    # Ensure start and destination are valid cities (strings)
    startCity = startCity.strip()
    destinationCity = destinationCity.strip()

    # If start and destination are the same, travel is always possible
    if startCity == destinationCity:
        return True

    # Build a directed graph and build connected components
    graph = {}
    visited = set()
    reachable = {}

    def dfs(city, components):
        """DFS to find all cities reachable from 'city' and mark them in 'components'"""
        if city not in visited:
            visited.add(city)
            components.add(city)
            for next_city in graph.get(city, []):
                dfs(next_city, components)
        elif city in components:
            pass  # Already processed

    # Add all routes as undirected edges
    for route in routes:
        u, v = route[0], route[1]
        if u in graph:
            graph[u].append(v)
        if v in graph:
            graph[v].append(u)

    # Find connected components using BFS/DFS
    def bfs(city, components):
        if city not in visited:
            visited.add(city)
            components.add(city)
            queue = deque([city])
            while queue:
                curr = queue.popleft()
                for neighbor in graph.get(curr, []):
                    if neighbor not in visited:
                        visited.add(neighbor)
                        components.add(neighbor)
                        queue.append(neighbor)
        elif city in components:
            pass

    components = set()

    # Run BFS from each city to find its component
    for city in graph:
        bfs(city, components)

    # If destination is not in any component, it's unreachable
    if destinationCity not in components:
        return False

    # If startCity == destinationCity, we're already here
    if startCity == destinationCity:
        return True

    return True
