def concatenate_k_lexicographically(words, k):
    """
    Sort the given `words` lexicographically and return the first `k` words
    concatenated into a single string.

    Raises ValueError if k > len(words).
    Returns empty string if k == 0.
    """
    if not isinstance(words, list):
        raise TypeError("words must be a list.")
    if k < 0:
        raise ValueError("k must be non-negative.")
    if k > len(words):
        raise ValueError("k cannot be greater than the number of words.")

    sorted_words = sorted(words)
    if k == 0:
        return ""

    return "".join(sorted_words[:k])
