def num_islands(grid):
    """
    Count the number of islands in a 2D grid.
    An island is defined as a connected group of '1's (land)
    horizontally or vertically. All '0's are treated as water.
    The grid has no external boundaries in our problem; 
    we assume all four sides of the sub-grid are water.

    Edge cases:
    - Empty grid [] returns 0.
    - Grid with no '1's returns 0.
    - Grid with all '0's returns 0.
    """
    if not grid:
        return 0

    m, n = len(grid), len(grid[0])
    islands = set()

    for r in range(m):
        for c in range(n):
            if grid[r][c] == '1':
                # Start a new island
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == '1':
                            stack.append((nr, nc))
                islands.add((cr, cc))

    return len(islands)
