from collections import deque

def num_islands(grid):
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    island_coords = set()

    def solve(r, c):
        # Start BFS/DFS from the given (r, c)
        if (r, c) in island_coords:
            return
        island_coords.add((r, c))
        queue = deque([(r, c)])

        while queue:
            r, c = queue.popleft()

            # Check adjacent up, down, left, right
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '1':
                    queue.append((nr, nc))
        # Mark entire island as visited by setting all cells to '0'
        # We do this by marking all cells in the discovered region as '0'
        for nr, nc in island_coords:
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = nr + dr, nc + dc
                grid[nr][nc] = '0'

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1':
                solve(r, c)
    return len(island_coords)


