def maxProfit(prices):
    if not prices or len(prices) <= 1:
        return 0

    buy = 0
    sell = 0

    # If we already bought on day 0, we can't buy again on or before day 0.
    # A transaction must be: buy on some day k > 0, sell on some day s > k with s <= k.

    for price in prices[1:]:
        # If buying has already happened (i.e., we bought at or before this day),
        # we can't buy again on this day or earlier.
        if buy > 0:
            continue

        # If selling has happened (i.e., we sold at or before this day),
        # we can't sell again on this day or later.
        if sell > 0:
            continue

        if price > buy:
            sell = price
        else:
            buy = price

    return sell - buy
