def group_and_sort_items(items):
    # Build a dictionary where the key is the type string
    type_names = {}
    for type_str, name_list in items:
        type_str = type_str[0]
        type_names[type_str] = set(name_list)

    # Group items by type
    grouped_items = {}
    for type_str, names in type_names.items():
        groups = []
        for name in names:
            if type_str not in grouped_items:
                grouped_items[type_str] = []
            grouped_items[type_str].append((name, type_str))
        # Sort groups by name alphabetically
        groups.sort(key=lambda x: x[0])

    # Build final list: (type, sorted_list)
    result = []
    for type_str, names in grouped_items.items():
        names_list = [name for name, _ in names]
        result.append([type_str, names_list])

    return result
