def get_primes_desc(numbers: list) -> list:
    """
    Returns a list of prime numbers from the input list in descending order.

    Parameters:
        numbers (list): A list of integers.

    Returns:
        list: A list of prime numbers, arranged in descending order.
    """
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = []
    for num in numbers:
        if is_prime(num):
            primes.append(num)

    return sorted(primes, reverse=True)
