from heapq import *
import queue

class MessageQueue:
    def __init__(self):
        self.messages: List[Dict[str, Any]] = []
        self.sent_messages: List[Dict[str, Any]] = []
        self.count_sent: int = 0

    def push(self, message: Dict[str, Any]) -> None:
        self.messages.append(message)

    def delete_message(self, index: int, sender_id: int) -> None:
        self.messages[index] = {}
        self.count_sent -= 1

    def get_count(self, sender_id: int) -> int:
        return self.count_sent

    def get_message_id(self, message_id: int, sender_id: int) -> None:
        self.messages[message_id] = {
            'id': message_id,
            'sender_id': sender_id,
            'timestamp': None,
            'processed': False
        }

    def mark_processed(self, sender_id: int) -> None:
        self.messages[self.messages[-1]['id']] = {'processed': True}

    def unmark_processed(self, sender_id: int) -> None:
        self.messages[-1]['processed'] = False

    def get_sent_count(self) -> int:
        return self.get_count(self.sender_id)

    def get_queue_size(self) -> int:
        return len(self.messages)


def count_unprocessed_messages(messages: List[Dict[str, Any]], sender_id: int) -> int:
    """
    Returns the number of messages sent by the given sender_id that are still in the queue
    and have not been processed yet.

    Args:
        messages: List of messages, each dict with keys 'id', 'sender_id', 'timestamp', 'processed'.
        sender_id: The sender ID to check.

    Returns:
        The count of unprocessed messages sent by this sender.
    """
    # Convert each message to the Queue format
    queue = MessageQueue()
    for msg in messages:
        queue.push(msg)

    # Get the number of sent messages from the queue
    sent_count = queue.get_sent_count()

    # If no messages, return 0
    if sent_count == 0:
        return 0

    # Remove unprocessed messages for the current sender
    for msg in messages:
        if msg['sender_id'] == sender_id and not msg['processed']:
            queue.delete_message(msg['id'], sender_id)
            queue.unmark_processed(sender_id)
            sent_count -= 1
        else:
            break

    # Return the remaining sent count
    return sent_count
