def max_candles_blown_out(T, test_cases):
    """
    Given T test cases, each containing N and a list of candles with heights.
    Find the maximum number of candles that can be blown out in one breath.
    A candle is blown out if all candles in that breath have the same maximum height.
    """
    # Dictionary to store the maximum count of each candle height
    height_counts = {}

    for N, candles in test_cases:
        # Initialize count for first candle
        h = candles[0]
        count = 1
        for c in candles:
            if c > h:
                count += 1
            elif c == h:
                count += 1

        # Add to the counts for other heights
        if h not in height_counts:
            height_counts[h] = 1
        height_counts[h] = height_counts.get(h, 0) + count

    # Iterate through all heights and find the maximum number of candles
    max_candles = 0
    for h, count in height_counts.items():
        if count > max_candles:
            max_candles = count

    return max_candles
